/**
 * Sections in the in-world menu (settingsMenu.ts), each a tab beside the
 * settings. A part of the shell that has one (the placements view's Build
 * section) adds it here; the first section turns the menu's panel into
 * pages: the settings rows become one, each section another, under a bar of
 * tabs shown only while some section is offered.
 *
 * Loaded with the part that adds a section, never on the first paint, so
 * the menu knows nothing of it: this finds the menu's panel in the page,
 * follows it being mounted and opened by watching the page, and closes it
 * with its own close button. Either side may come first.
 */

export interface MenuSection {
  id: string;
  title: string;
  body: HTMLElement;
  /** Whether its tab is offered right now; asked each time the menu opens. */
  shown(): boolean;
  /** Told when its tab is opened, to draw what may have changed. */
  opened?(): void;
}

/** A section's body sends this (bubbling) to close the menu, as after choosing an item to place. */
export const CLOSE_MENU_EVENT = 'webverse-menu-close';

const PANEL = '[data-webverse-menu]';

interface Tabs {
  sections: MenuSection[];
  /** The panel the tabs are drawn in, and what redraws them. */
  panel?: HTMLElement;
  draw?: () => void;
  offer?: () => void;
  watching?: MutationObserver;
}
const byDoc = new WeakMap<Document, Tabs>();

export const menuSectionsOf = (doc: Document): readonly MenuSection[] => byDoc.get(doc)?.sections ?? [];

/** Asks the sections again whether they are offered, as when what a section depends on changed while the menu is open. */
export const offerMenuSections = (doc: Document): void => byDoc.get(doc)?.offer?.();

/** Adds a section (one with the same id is replaced); returns what takes it away again. */
export function addMenuSection(doc: Document, section: MenuSection): () => void {
  let t = byDoc.get(doc);
  if (!t) byDoc.set(doc, (t = { sections: [] }));
  const tabs = t;
  tabs.sections = [...tabs.sections.filter((s) => s.id !== section.id), section];
  follow(doc, tabs);
  tabs.draw?.();
  return () => {
    if (!tabs.sections.includes(section)) return;
    tabs.sections = tabs.sections.filter((s) => s !== section);
    tabs.draw?.();
  };
}

/** Draws the tabs in the menu on the page now, and in each one mounted later (a new world mounts a new menu). */
function follow(doc: Document, tabs: Tabs): void {
  const find = (): void => {
    const panel = doc.querySelector<HTMLElement>(PANEL);
    if (panel && panel !== tabs.panel) {
      tabs.panel = panel;
      ({ draw: tabs.draw, offer: tabs.offer } = attach(doc, panel, tabs));
    }
  };
  find();
  if (tabs.watching || typeof MutationObserver === 'undefined') return;
  tabs.watching = new MutationObserver(find);
  tabs.watching.observe(doc.body, { childList: true });
}

/** Turns a menu's panel into pages and tabs; returns what redraws them, and what asks again which are offered. */
function attach(doc: Document, panel: HTMLElement, tabs: Tabs): { draw: () => void; offer: () => void } {
  const bar = doc.createElement('div');
  bar.setAttribute('data-webverse-menu-tabs', '');
  bar.setAttribute('role', 'tablist');
  bar.style.cssText = 'display:flex;gap:6px;margin:0 0 8px';
  const settings = doc.createElement('div');
  settings.setAttribute('data-webverse-menu-page', 'settings');
  const pages = doc.createElement('div');
  // The settings rows are everything between the title and the close button.
  const title = panel.querySelector('h2');
  const close = panel.querySelector<HTMLElement>('[data-webverse-menu-close]');
  for (const el of [...panel.children]) if (el !== title && el !== close) settings.appendChild(el);
  panel.insertBefore(bar, close);
  panel.insertBefore(settings, close);
  panel.insertBefore(pages, close);
  pages.addEventListener(CLOSE_MENU_EVENT, () => close?.click());

  let current = 'settings';
  const show = (id: string): void => {
    current = id;
    for (const page of [settings, ...pages.children] as HTMLElement[]) page.hidden = page.getAttribute('data-webverse-menu-page') !== id;
    for (const tab of [...bar.children] as HTMLElement[]) tab.setAttribute('aria-selected', String(tab.getAttribute('data-webverse-menu-tab') === id));
    tabs.sections.find((s) => s.id === id)?.opened?.();
  };
  const tab = (id: string, text: string): HTMLButtonElement => {
    const b = doc.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'tab');
    b.setAttribute('data-webverse-menu-tab', id);
    b.textContent = text;
    b.style.cssText = 'flex:1;padding:6px;font:inherit;color:#fff;cursor:pointer;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.3);border-radius:6px';
    b.addEventListener('click', () => show(id));
    return b;
  };
  /** Which tabs are offered right now; a page that is not falls back to the settings. */
  const offer = (): void => {
    let any = false;
    for (const s of tabs.sections) {
      const shown = s.shown();
      any ||= shown;
      const t = bar.querySelector<HTMLElement>(`[data-webverse-menu-tab="${s.id}"]`);
      if (t) t.hidden = !shown;
      if (!shown && current === s.id) current = 'settings';
    }
    bar.hidden = !any;
    show(current);
  };
  // Each time the menu opens, what is offered is asked again.
  if (typeof MutationObserver !== 'undefined') {
    new MutationObserver(() => {
      if (!panel.hidden) offer();
    }).observe(panel, { attributes: true, attributeFilter: ['hidden'] });
  }
  const draw = (): void => {
    bar.replaceChildren(tab('settings', 'Settings'), ...tabs.sections.map((s) => tab(s.id, s.title)));
    pages.replaceChildren(
      ...tabs.sections.map((s) => {
        const page = doc.createElement('div');
        page.setAttribute('data-webverse-menu-page', s.id);
        page.append(s.body);
        return page;
      }),
    );
    if (!tabs.sections.some((s) => s.id === current)) current = 'settings';
    offer();
  };
  draw();
  return { draw, offer };
}
