/**
 * The three doors into import mode: a file dropped anywhere on the page, an
 * Import section in the menu with a file picker, and a link on the app
 * address (`?import=<url>`, importLink.ts) that is fetched. All hand the
 * files to the import chunk, which is fetched only then. Loaded after boot,
 * so the first paint knows nothing of it.
 */
import { addMenuSection, CLOSE_MENU_EVENT } from '../settings/menuTabs';
import { blendWindowMode } from './blendHandback';
import { IMPORT_MODEL_EXTS, type ImportFile } from './importFiles';
import { fetchImportLink, isListing, isLoopback, LinkUnreachable, LOOPBACK_HINT, nameFromUrl, readImportLink, withoutImportParam } from './importLink';
import type { ImportDeps } from './importMode';
import { convertInBrowser, isImportFrame, mountImportFrame, stageInBrowser } from './importFrame';
import { isHandBack, isIsolationRequest, plainUrl } from './isolation';
import { createWorldRules, pageOriginOf } from '../net/worldRequests';

async function toImportFiles(list: FileList | File[]): Promise<ImportFile[]> {
  const files = Array.from(list);
  return Promise.all(files.map(async (f) => ({ name: f.name, bytes: new Uint8Array(await f.arrayBuffer()) })));
}

export function mountImportEntry(doc: Document, deps: ImportDeps): () => void {
  // The page kept for a visitor's file takes it from the page around it and no other way: no drop, no menu, no link.
  if (isImportFrame(doc) && doc.defaultView) {
    const own = doc.defaultView;
    // Opened as a window of its own, with the word for it in its address, it is one of Blender's two windows.
    if (own.parent === own && blendWindowMode(own.location.href) !== null) {
      void import('./blendWindow').then((mod) => mod.mountBlendWindow(doc, deps)).catch(() => undefined);
      return () => undefined;
    }
    return mountImportFrame(own, deps, stageInBrowser(own), convertInBrowser(doc, deps));
  }
  let disposed = false;
  const open = async (list: FileList | File[]): Promise<void> => {
    const files = await toImportFiles(list);
    if (disposed) return;
    const { runImport } = await import('./importMode');
    if (disposed) return;
    await runImport(doc, files, deps);
  };

  // A link on the app address: fetched, then imported as a dropped file. The
  // stage says what it is doing meanwhile, and what to do when this
  // computer's own address refused the page.
  const openLink = async (url: string): Promise<void> => {
    const name = isListing(url, null) ? 'the linked model' : nameFromUrl(url);
    const mod = await import('./importMode');
    if (disposed) return;
    mod.showStage(doc, 'converting', `Opening ${name}`, [`Fetching from ${new URL(url).host}…`]);
    let files: ImportFile[];
    try {
      // The link is anyone's to write: a link to another site is fetched without the page's cookies, and may not
      // lead on to a file on the page's own site.
      files = await fetchImportLink(url, createWorldRules({ pageOrigin: pageOriginOf(doc.defaultView?.location) }).accessFor(url).fetch);
    } catch (err) {
      if (disposed) return;
      // No answer at all from this computer's own address is what the browser's refusal looks like from here.
      const hint = err instanceof LinkUnreachable && isLoopback(url) ? [LOOPBACK_HINT] : [];
      const lines = [err instanceof Error ? err.message : String(err), ...hint];
      mod.showStage(doc, 'failed', `Could not open ${name}`, lines, [{ label: 'Close', run: () => mod.showStage(doc, 'closed') }]);
      return;
    }
    if (disposed) return;
    await mod.runImport(doc, files, deps);
  };

  // Dropping a file on the page: the browser would otherwise open it as a download.
  const onDragOver = (e: DragEvent): void => {
    if (e.dataTransfer?.types.includes('Files')) e.preventDefault();
  };
  const onDrop = (e: DragEvent): void => {
    const files = e.dataTransfer?.files;
    if (!files || files.length === 0) return;
    e.preventDefault();
    void open(files);
  };
  doc.addEventListener('dragover', onDragOver);
  doc.addEventListener('drop', onDrop);

  // A page that reloaded itself isolated for Blender picks up the file it
  // kept; the ordinary page it hands back to picks up the converted world.
  const win = doc.defaultView;
  if (win && isIsolationRequest(win.location.href)) {
    void import('./blendImport')
      .then(({ resumePendingImport }) => (disposed ? undefined : resumePendingImport(doc, deps)))
      .catch(() => {});
  } else if (win && isHandBack(win.location.href)) {
    // The note is taken off the address once read, so a reload does not look again.
    try {
      win.history.replaceState(win.history.state, '', plainUrl(win.location.href));
    } catch {
      // A page that cannot rewrite its address still opens the world.
    }
    void import('./blendImport')
      .then(({ resumeOpenedWorld }) => (disposed ? undefined : resumeOpenedWorld(doc, deps)))
      .catch(() => {});
  } else if (win) {
    // The link is taken off the address before anything runs, so a reload,
    // or the page's own reload for Blender, does not import it again.
    const link = readImportLink(win.location.search, win.location.hash);
    if (link) {
      try {
        win.history.replaceState(win.history.state, '', withoutImportParam(win.location.href));
      } catch {
        // A page that cannot rewrite its address still imports once.
      }
      void openLink(link);
    }
  }

  // The menu's Import section: what opens, and a picker.
  const body = doc.createElement('div');
  const p = doc.createElement('p');
  p.textContent =
    `Open a model as a world: SketchUp (.skp), Blender (.blend), Collada (.dae), OBJ, FBX or glb. ` +
    `Drop the file on the page, or choose it here. A .dae or .obj with textures: choose the images with it.`;
  const input = doc.createElement('input');
  input.type = 'file';
  input.multiple = true;
  input.accept = [...IMPORT_MODEL_EXTS, '.blend', '.png', '.jpg', '.jpeg', '.webp'].join(',');
  input.setAttribute('data-webverse-import-input', '');
  input.style.display = 'none';
  const button = doc.createElement('button');
  button.type = 'button';
  button.textContent = 'Choose a model…';
  button.setAttribute('data-webverse-import-choose', '');
  button.addEventListener('click', () => input.click());
  input.addEventListener('change', () => {
    if (!input.files || input.files.length === 0) return;
    body.dispatchEvent(new Event(CLOSE_MENU_EVENT, { bubbles: true }));
    void open(input.files);
    input.value = '';
  });
  body.append(p, button, input);
  const removeSection = addMenuSection(doc, { id: 'import', title: 'Import', body, shown: () => true });

  return () => {
    disposed = true;
    doc.removeEventListener('dragover', onDragOver);
    doc.removeEventListener('drop', onDrop);
    removeSection();
  };
}
