/**
 * Import by link: the third door into import mode, beside the drop and the
 * picker. The app address carries `?import=<url>`; the shell fetches what
 * is there and hands it to the stage as if it had been dropped. The link is
 * either a model file, or a listing: a small JSON document naming the
 * model and the files that go beside it (a `.blend` and its textures), all
 * on the listing's own origin. The Blender add-on in this repository uses
 * it: it serves the saved file on 127.0.0.1 and opens the browser on the
 * link.
 *
 * The listing's shape and the parameter are this shell's own, shared with
 * that add-on and nothing else: not a published contract, and free to
 * change with both. Should another program want to hand files to a shell,
 * the shape would first be specified where the shell's other addresses
 * are, and this comment would point there.
 *
 * The parameter is consumed: taken from the address before anything runs,
 * so a reload, or the page's own reload for Blender, never imports twice.
 * Pure: nothing here touches a window; the entry wires it.
 */
import { readReservedParam } from '../navigation/reservedParams';
import type { ImportFile } from './importFiles';

export const IMPORT_PARAM = 'import' as const;

/** The most files a listing may name: a model and its textures, not a drive. */
export const LISTING_MAX_FILES = 200;

type Fetch = (url: string, init?: RequestInit) => Promise<Response>;

const httpUrl = (raw: string, base?: string): URL | null => {
  try {
    const u = new URL(raw, base);
    return u.protocol === 'http:' || u.protocol === 'https:' ? u : null;
  } catch {
    return null;
  }
};

/** The link the app address carries, as an absolute http(s) address, or null. */
export function readImportLink(search: string, hash: string): string | null {
  const raw = readReservedParam(IMPORT_PARAM, search, hash);
  if (!raw) return null;
  return httpUrl(raw.trim())?.href ?? null;
}

/** `a=1&import=x&b=2` without the import pair, the other pairs' spelling untouched. */
function dropPair(query: string): string {
  return query
    .split('&')
    .filter((pair) => {
      if (!pair) return false;
      const key = pair.split('=')[0] ?? '';
      try {
        return decodeURIComponent(key) !== IMPORT_PARAM;
      } catch {
        return true;
      }
    })
    .join('&');
}

/** The address with the link taken out of both the query and the hash; everything else kept as written. */
export function withoutImportParam(href: string): string {
  const u = new URL(href);
  const search = dropPair(u.search.replace(/^\?/, ''));
  const hash = dropPair(u.hash.replace(/^#/, ''));
  u.search = search ? `?${search}` : '';
  u.hash = hash ? `#${hash}` : '';
  return u.href;
}

/** A file name from an address: its last path segment, decoded; `model` when there is none. */
export function nameFromUrl(url: string): string {
  try {
    const last = new URL(url).pathname.split('/').filter(Boolean).pop() ?? '';
    const name = decodeURIComponent(last).trim();
    return name || 'model';
  } catch {
    return 'model';
  }
}

/** Whether an address, and what it answered, is a listing rather than a model. */
export function isListing(url: string, contentType: string | null): boolean {
  if (contentType && /\bapplication\/json\b|\+json\b/i.test(contentType)) return true;
  return /\.json$/i.test(nameFromUrl(url));
}

const PLAIN_NAME = /^[^/\\]{1,255}$/;

/**
 * The files a listing names: `{ "files": [ { "name", "url" } ] }`. A name is
 * a plain file name, as a dropped file has one; every address is on the
 * listing's own origin, so a listing hands over its author's files and no
 * one else's. Throws with a sentence for a listing that is not this.
 */
export function filesFromListing(json: unknown, listingUrl: string): Array<{ name: string; url: string }> {
  const origin = httpUrl(listingUrl)?.origin;
  const files = (json && typeof json === 'object' ? (json as { files?: unknown }).files : undefined) ?? null;
  if (!origin || !Array.isArray(files)) throw new Error('The listing names no files.');
  if (files.length === 0) throw new Error('The listing names no files.');
  if (files.length > LISTING_MAX_FILES) throw new Error(`The listing names ${files.length} files; at most ${LISTING_MAX_FILES} are taken.`);
  const out: Array<{ name: string; url: string }> = [];
  const seen = new Set<string>();
  for (const f of files as unknown[]) {
    const e = (f ?? {}) as { name?: unknown; url?: unknown };
    const name = typeof e.name === 'string' ? e.name.trim() : '';
    if (!PLAIN_NAME.test(name) || name === '.' || name === '..') throw new Error(`The listing names a file it cannot: ${JSON.stringify(e.name ?? '')}.`);
    const url = typeof e.url === 'string' ? httpUrl(e.url, listingUrl) : null;
    if (!url) throw new Error(`The listing gives no address for ${name}.`);
    if (url.origin !== origin) throw new Error(`The listing points ${name} at another host; a listing hands over its own files only.`);
    if (seen.has(name)) continue;
    seen.add(name);
    out.push({ name, url: url.href });
  }
  return out;
}

/** Whether an address is this computer's own: where the browser may ask before it lets a page reach it. */
export function isLoopback(url: string): boolean {
  const host = httpUrl(url)?.hostname ?? '';
  return host === '127.0.0.1' || host === 'localhost' || host === '[::1]' || /^127\./.test(host);
}

/** What to do when a fetch of this computer's own address fails: the browser's one question. */
export const LOOPBACK_HINT = 'If the browser asked whether this page may reach your computer, allow it and open the link again.';

/** The fetch itself failed: no answer at all, which on a loopback address is what the browser's refusal looks like. */
export class LinkUnreachable extends Error {
  constructor(url: string, cause: unknown) {
    super(`Could not fetch ${nameFromUrl(url)} from ${new URL(url).host}: ${cause instanceof Error ? cause.message : String(cause)}`);
    this.name = 'LinkUnreachable';
  }
}

async function fetchBytes(url: string, fetchImpl: Fetch): Promise<{ bytes: Uint8Array; contentType: string | null }> {
  let res: Response;
  try {
    res = await fetchImpl(url);
  } catch (err) {
    throw new LinkUnreachable(url, err);
  }
  if (!res.ok) throw new Error(`${new URL(url).host} answered ${res.status} for ${nameFromUrl(url)}.`);
  return { bytes: new Uint8Array(await res.arrayBuffer()), contentType: res.headers.get('content-type') };
}

/** The files behind a link, fetched: the one model, or everything a listing names. */
export async function fetchImportLink(url: string, fetchImpl: Fetch): Promise<ImportFile[]> {
  const first = await fetchBytes(url, fetchImpl);
  if (!isListing(url, first.contentType)) return [{ name: nameFromUrl(url), bytes: first.bytes }];
  let json: unknown;
  try {
    json = JSON.parse(new TextDecoder().decode(first.bytes));
  } catch {
    throw new Error('The listing is not JSON.');
  }
  const named = filesFromListing(json, url);
  return Promise.all(named.map(async (f) => ({ name: f.name, bytes: (await fetchBytes(f.url, fetchImpl)).bytes })));
}
