/**
 * Blender's two windows, for a page that cannot run it: their addresses, and
 * the note that says who a converted world is for.
 *
 * Blender's converter needs a page the browser has isolated, and a page with
 * other sites' frames in it cannot be one. So the page around a world frame
 * opens a window for it. That window is on the host kept for a visitor's
 * files, never on the opening page's own origin: the converter runs code
 * that page's policy forbids, on a file a stranger may have made.
 *
 * Two facts about browsers shape the rest:
 *
 *  - Storage is partitioned by the site in the address bar. A frame on the
 *    files host inside the opening page, and a window on the files host by
 *    itself, do not see each other's cache. Two windows on the files host
 *    do.
 *  - Isolating a window cuts its link to the window that opened it. The
 *    converter cannot be handed a file once it is isolated, and cannot say
 *    when it is done.
 *
 * So there are two windows, each opened by a press of the visitor's:
 *
 *   convert  opens plain, is handed the file by the page that opened it,
 *            keeps the file and a note of that page's origin in its own
 *            cache, reloads itself isolated, converts, and leaves the world
 *            in the cache. It says on its own card when it is ready.
 *   take     opens plain, finds the world in the same cache, posts it to
 *            the page that opened it, only at the origin the note names,
 *            forgets it, and closes.
 *
 * Zero imports.
 */

/** The word in the address that says which of the two windows a page is. */
export const BLEND_PARAM = 'blend';
export type BlendWindowMode = 'convert' | 'take';

/** How long a file or a converted world is kept for the second window, in ms. Older than this it is forgotten, not given. */
export const HANDBACK_FOR_MS = 60 * 60 * 1000;

/** The address of one of the two windows: the files host's page at `importPage`, and the one word. */
export function blendWindowUrl(importPage: string, mode: BlendWindowMode): string {
  const url = new URL(importPage);
  url.search = '';
  url.hash = '';
  url.searchParams.set(BLEND_PARAM, mode);
  return url.href;
}

/** Which window the page at `href` was opened as; null when it is neither. */
export function blendWindowMode(href: string): BlendWindowMode | null {
  try {
    const word = new URL(href).searchParams.get(BLEND_PARAM);
    return word === 'convert' || word === 'take' ? word : null;
  } catch {
    return null;
  }
}

/**
 * How far the converting window has got, in the order it happens: waiting
 * to be handed the file; the file kept; reloaded isolated; loading Blender;
 * starting it; converting; Blender done, its output `converted`; the world
 * being built and put in the store (`staging`); and then the world ready,
 * or the work failed.
 */
export const BLEND_PROGRESS = ['waiting', 'kept', 'isolated', 'loading', 'starting', 'converting', 'converted', 'staging', 'ready', 'failed'] as const;
export type BlendProgress = (typeof BLEND_PROGRESS)[number];

/** How long the converting window may say nothing before it is taken to be closed or stuck, in ms. A window out of sight is slowed by the browser, so this is generous. */
export const STOPPED_AFTER_MS = 90_000;
/** The longest reason kept for a failure. */
const MAX_WHY_LENGTH = 300;
/** The longest line kept of what Blender last said, or of one error. */
export const MAX_NOTE_LINE = 200;
/** How many errors a note keeps: the first ones, since the first is most often the cause. */
export const MAX_NOTE_ERRORS = 5;

/**
 * The converting window's note, in the files host's cache: who the world is
 * for, and how far the work has got. The window writes it as it goes, so
 * the second window can answer truthfully, and so whoever looks in the
 * cache can see where a conversion stopped.
 */
export interface HandbackNote {
  /** The origin of the page that handed the file over: the only one its world is posted to. Null only while the window still waits for the file. */
  origin: string | null;
  /** When the file was kept, and once the world is ready, when that was: a ready world older than `HANDBACK_FOR_MS` is not given. */
  at: number;
  stage: BlendProgress;
  /** When the window last wrote this note. It writes every few seconds while it works. */
  beat: number;
  /** How much of Blender has loaded, 0 to 100, while loading. */
  percent?: number;
  /** Why the work failed, as one line. It stays on the files host: it is never sent to the page that opened the window. */
  why?: string;
  /**
   * What Blender said last, and how many lines it has said: with `beat`,
   * whoever reads the note can tell a window still at work with Blender
   * silent from one that stopped altogether. Like `why`, these and
   * `errors` stay on the files host.
   */
  last?: string;
  lines?: number;
  /** What went wrong around Blender that nobody saw: the window's own errors, its workers', files answered with an error. */
  errors?: string[];
}

const oneLine = (text: string, longest = MAX_WHY_LENGTH): string => text.replace(/\s+/g, ' ').trim().slice(0, longest);
const shortLine = (text: string): string => oneLine(text, MAX_NOTE_LINE);

export const handbackNote = (note: HandbackNote): string =>
  JSON.stringify({
    origin: note.origin,
    at: note.at,
    stage: note.stage,
    beat: note.beat,
    ...(note.percent !== undefined ? { percent: note.percent } : {}),
    ...(note.why !== undefined ? { why: oneLine(note.why) } : {}),
    ...(note.last !== undefined ? { last: shortLine(note.last) } : {}),
    ...(note.lines !== undefined ? { lines: note.lines } : {}),
    ...(note.errors !== undefined && note.errors.length > 0 ? { errors: note.errors.slice(0, MAX_NOTE_ERRORS).map(shortLine) } : {}),
  });

/**
 * What the second window answers when it is asked for the world, from the
 * note as of `now`: the world is `ready`; the window is still `converting`
 * (at any stage before the end, and heard from lately); it said it
 * `failed`; it has `stopped`, having said nothing for a while, which is a
 * window closed or stuck; or there is no note, and the answer is `empty`.
 */
export function handbackAnswer(note: HandbackNote | null, now: number): 'ready' | 'converting' | 'failed' | 'stopped' | 'empty' {
  if (note === null) return 'empty';
  if (note.stage === 'ready' || note.stage === 'failed') return note.stage;
  return now - note.beat > STOPPED_AFTER_MS ? 'stopped' : 'converting';
}

/** An origin a page can be on, written exactly as the browser writes one. */
export function isWebOrigin(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  try {
    const url = new URL(value);
    return (url.protocol === 'https:' || url.protocol === 'http:') && url.origin === value;
  } catch {
    return false;
  }
}

/**
 * The note in `text` as of `now`, or null when it is not one, is dated
 * ahead, or says a world is ready that is older than a world is kept.
 * Read field by field, as a stranger's. Never throws.
 */
export function readHandbackNote(text: string | null, now: number): HandbackNote | null {
  try {
    if (text === null) return null;
    const fields = JSON.parse(text) as unknown;
    if (typeof fields !== 'object' || fields === null || Array.isArray(fields)) return null;
    const { origin, at, stage, beat, percent, why, last, lines, errors } = fields as Record<string, unknown>;
    if (typeof at !== 'number' || !Number.isFinite(at) || at > now) return null;
    if (typeof beat !== 'number' || !Number.isFinite(beat)) return null;
    if (!(BLEND_PROGRESS as readonly unknown[]).includes(stage)) return null;
    const reached = stage as BlendProgress;
    // Nobody is named only while the window still waits for its file.
    if (!(isWebOrigin(origin) || (origin === null && reached === 'waiting'))) return null;
    if (reached === 'ready' && now - at > HANDBACK_FOR_MS) return null;
    return {
      origin,
      at,
      stage: reached,
      beat,
      ...(typeof percent === 'number' && Number.isFinite(percent) ? { percent: Math.max(0, Math.min(100, Math.round(percent))) } : {}),
      ...(typeof why === 'string' ? { why: oneLine(why) } : {}),
      ...(typeof last === 'string' ? { last: shortLine(last) } : {}),
      ...(typeof lines === 'number' && Number.isSafeInteger(lines) && lines >= 0 ? { lines } : {}),
      ...(Array.isArray(errors)
        ? { errors: errors.filter((each): each is string => typeof each === 'string').slice(0, MAX_NOTE_ERRORS).map(shortLine) }
        : {}),
    };
  } catch {
    return null;
  }
}
