/**
 * The frame that turns a visitor's model into a world, and shows it.
 *
 * Under frames, the page around a world runs no world and converts no
 * model: it is the page a visitor trusts to say where they are, and a model
 * is a stranger's file. Both happen here instead. This page is the client at
 * the frame address, marked in its own markup
 * (`<meta name="webverse-import-frame">`), and it differs from a world frame
 * in what it opens: worlds on its own origin only, which is the rule of any
 * client page that lists no other origin, and the only worlds there are the
 * ones made or handed over here.
 *
 * It listens for two messages (importHandoff.ts), from the page around it
 * and no other window:
 *
 *  - model files, as they came off the visitor's computer. It converts
 *    them with the converter any client page uses, shows the world, and
 *    posts the world's files back, so the page around it can offer to save
 *    or publish them.
 *  - a world already built (Blender's, which is converted elsewhere). It
 *    only shows it.
 *
 * Either way the files go into this origin's own store, the import worker
 * answers for them, and the world is loaded by address as any world is. It
 * tells the page around it that it is ready, that the world opened or that
 * it did not, and, as a world frame does, when the visitor is walking in
 * it. What went wrong is shown here, in this frame's own card; the page
 * around it is told only that something did.
 *
 * The page around it is whoever embeds it and is not trusted with anything:
 * all a stranger's page gains by handing it files is a world shown in a
 * frame, and the files of that world back, which it supplied. Nothing is
 * kept here that a world could want: no sign-in, no publish, no save.
 */
import { frameMessage, type ImportState } from '../frame/frameMessages';
import { reportFileDrags, reportWalking, type WalkingDocument } from '../frame/frameWalking';
import { isImmersiveVrSupported } from '../xr/xrSupport';
import { classifyImport } from './importFiles';
import { importHandoff, readImportHandoff, readImportModels, type HandoffFile, type ImportHandoff, type ModelFile } from './importHandoff';
import type { VemlParseResult } from '../veml/parser';

/** The `<meta name>` by which a page says it shows worlds it is handed. */
export const IMPORT_FRAME_META = 'webverse-import-frame';

/** True when the page's own markup says it is the import frame. */
export function isImportFrame(doc: { querySelector(selector: string): unknown }): boolean {
  return doc.querySelector(`meta[name="${IMPORT_FRAME_META}"]`) !== null;
}

/** The slice of `window` the import frame needs. `parent` is the window itself when no page is around it. */
export interface ImportFrameWindow {
  location: { hostname: string };
  parent: unknown;
  addEventListener(type: 'message', listener: (event: { source: unknown; data: unknown }) => void): void;
  removeEventListener(type: 'message', listener: (event: { source: unknown; data: unknown }) => void): void;
  /** The page's document, for knowing when the visitor is walking; a test may leave it out. */
  document?: WalkingDocument;
}

export interface ImportFrameDeps {
  loadWorld(url: string): Promise<VemlParseResult>;
  clearWorld(): void;
}

/** Puts a world's files where this page can load them by address, and gives the address of its document. */
export type StageFiles = (files: readonly HandoffFile[]) => Promise<string>;

/**
 * Converts model files and shows the world. Calls `handBack` once with the
 * world and whether it opened here; a model that could not be converted
 * resolves without calling it.
 */
export type ConvertModels = (models: readonly ModelFile[], handBack: (world: ImportHandoff, shown: boolean) => void) => Promise<void>;

/** Staging through the import worker and this origin's cache, forgetting whatever an earlier world left. */
export function stageInBrowser(win: Window): StageFiles {
  return async (files) => {
    const [{ ensureImportServer }, { stageWorldFiles }] = await Promise.all([import('./importServer'), import('./worldInMemory')]);
    const server = await ensureImportServer(win);
    await server.store.clear?.();
    return (await stageWorldFiles(files, server.store, server.scopeUrl)).documentUrl;
  };
}

/** Converting with the client's own converter, which is fetched when a model arrives and shows its own progress. */
export function convertInBrowser(doc: Document, deps: ImportFrameDeps): ConvertModels {
  return async (models, handBack) => {
    const { runImport } = await import('./importMode');
    await runImport(doc, models, {
      ...deps,
      handBack: (world, shown) => handBack({ title: world.title, files: world.files.map((f) => ({ path: f.path, bytes: f.bytes })) }, shown),
    });
  };
}

/** Start listening for a model to convert or a world to show. Returns the function that stops it. */
export function mountImportFrame(
  win: ImportFrameWindow,
  deps: ImportFrameDeps,
  stage: StageFiles,
  convert: ConvertModels,
  vrSupported: () => Promise<boolean> = () => isImmersiveVrSupported(),
): () => void {
  // With no page around it nobody can hand it anything, and it listens to nobody.
  if (win.parent === win) return () => undefined;
  const outer = win.parent as { postMessage(message: unknown, targetOrigin: string): void };
  const post = (message: unknown): void => {
    try {
      outer.postMessage(message, '*');
    } catch {
      // The page around the frame is gone: nothing to tell.
    }
  };
  // Whether this frame offers its own Enter VR button, told as it opens a world, so the page around it can
  // leave the button room at its bar's end.
  let vr = false;
  void vrSupported().then(
    (yes) => void (vr = yes),
    () => undefined,
  );
  const tell = (state: ImportState): void =>
    post(frameMessage(state === 'opened' && vr ? { type: 'import', state, vr: true } : { type: 'import', state }));
  // Walking in one's own file is walking: the page around it steps its bar aside here as in any world, and
  // this page's own Enter VR button by the mark it puts on itself (framedPage.css).
  if (win.document) {
    const marked = win.document as WalkingDocument & { documentElement?: { toggleAttribute(name: string, on: boolean): void } };
    reportWalking(win.document, (on) => {
      marked.documentElement?.toggleAttribute('data-webverse-walking', on);
      post(frameMessage({ type: 'walking', on }));
    });
    // A file dragged over this world: the page around it puts a place to drop it over the frame.
    reportFileDrags(win.document, () => post(frameMessage({ type: 'dragging' })));
  }
  let turn = 0;

  /** Show a world that is already built. */
  const show = async (world: ImportHandoff, mine: number): Promise<void> => {
    try {
      const documentUrl = await stage(world.files);
      if (mine !== turn) return;
      deps.clearWorld();
      const result = await deps.loadWorld(documentUrl);
      if (mine === turn) tell(result.ok ? 'opened' : 'failed');
    } catch {
      if (mine === turn) tell('failed');
    }
  };
  /** Convert model files, show the world, and hand its files back. */
  const make = async (models: readonly ModelFile[], mine: number): Promise<void> => {
    let handed = false;
    try {
      // Blender's converter needs a page of its own; nothing here can run it.
      if (classifyImport(models).kind !== 'blend') {
        await convert(models, (world, shown) => {
          if (mine !== turn || handed) return;
          handed = true;
          post(importHandoff(world.title, world.files));
          tell(shown ? 'opened' : 'failed');
        });
      }
    } catch {
      // Told below, like any model that did not become a world.
    }
    if (!handed && mine === turn) tell('failed');
  };

  const onMessage = (event: { source: unknown; data: unknown }): void => {
    if (event.source !== outer) return;
    const world = readImportHandoff(event.data);
    const models = world === null ? readImportModels(event.data) : null;
    if (world === null && models === null) return;
    // A later file replaces an earlier one still being opened.
    const mine = (turn += 1);
    void (world !== null ? show(world, mine) : make(models!, mine));
  };
  win.addEventListener('message', onMessage);
  tell('ready');
  return () => win.removeEventListener('message', onMessage);
}
