/**
 * Which files, dropped or picked, enter import mode.
 *
 * One model per import: the file whose extension the converter reads. Every
 * other file rides beside it by name, which is how a Collada or OBJ model
 * finds its texture images. The answer is a classification, never a throw:
 * what is refused says why, so the stage can show it.
 */

export interface ImportFile {
  /** The file's own name, no directory. */
  name: string;
  bytes: Uint8Array;
}

/** The model formats the converter reads from bytes; a `.gltf` with files beside it is not one of them. */
export const IMPORT_MODEL_EXTS = ['.skp', '.dae', '.obj', '.fbx', '.glb'] as const;

export type ImportClassification =
  | { kind: 'model'; model: ImportFile; sidecars: Map<string, Uint8Array> }
  /** A `.blend`: Blender itself converts it, in WebAssembly, on an isolated page. */
  | { kind: 'blend'; model: ImportFile; sidecars: Map<string, Uint8Array> }
  | { kind: 'refused'; reason: string };

const extOf = (name: string): string => {
  const dot = name.lastIndexOf('.');
  return dot < 0 ? '' : name.slice(dot).toLowerCase();
};

export function classifyImport(files: readonly ImportFile[]): ImportClassification {
  if (files.length === 0) return { kind: 'refused', reason: 'Nothing to open.' };
  const models = files.filter((f) => (IMPORT_MODEL_EXTS as readonly string[]).includes(extOf(f.name)) || extOf(f.name) === '.blend');
  if (models.length === 0) {
    return {
      kind: 'refused',
      reason: `No model among these files. A model is one of ${IMPORT_MODEL_EXTS.join(', ')} or .blend; textures can come beside it.`,
    };
  }
  if (models.length > 1) {
    return {
      kind: 'refused',
      reason: `One model at a time: these are ${models.length} (${models.map((m) => m.name).join(', ')}).`,
    };
  }
  const model = models[0]!;
  const sidecars = new Map<string, Uint8Array>();
  for (const f of files) if (f !== model) sidecars.set(f.name, f.bytes);
  return { kind: extOf(model.name) === '.blend' ? 'blend' : 'model', model, sidecars };
}
