/**
 * The address that asks the import server to isolate the page.
 *
 * Blender's threaded build needs a cross-origin isolated page, which only
 * the headers of the page's own response can grant. The import service
 * worker adds them to a navigation whose address carries `isolate=1`; the
 * page reloads itself at that address, finds the file it kept, and goes on.
 * `isIsolationRequest` is the worker's half of the agreement, kept here so
 * the two never drift; the worker is plain script and repeats the one line.
 */

export const ISOLATE_PARAM = 'isolate';

/** The page's own address with `isolate=1`, and no world fragment: the import is the page's purpose now. */
export function isolatedUrl(href: string): string {
  const url = new URL(href);
  url.searchParams.set(ISOLATE_PARAM, '1');
  url.hash = '';
  return url.href;
}

/**
 * The address the isolated page leaves by: no isolation asked, and a note
 * that a converted world waits in the store. The note rides on the address
 * because nothing the tab stores survives the step out of isolation; the
 * browser gives the ordinary page a fresh session storage.
 */
export function handBackUrl(href: string): string {
  const url = new URL(href);
  url.searchParams.set(ISOLATE_PARAM, 'done');
  url.hash = '';
  return url.href;
}

export function isHandBack(href: string): boolean {
  try {
    return new URL(href).searchParams.get(ISOLATE_PARAM) === 'done';
  } catch {
    return false;
  }
}

/** The page's own address with nothing about isolation on it: what the ordinary page shows once it has read the note. */
export function plainUrl(href: string): string {
  const url = new URL(href);
  url.searchParams.delete(ISOLATE_PARAM);
  url.hash = '';
  return url.href;
}

export function isIsolationRequest(href: string): boolean {
  try {
    return new URL(href).searchParams.get(ISOLATE_PARAM) === '1';
  } catch {
    return false;
  }
}
