/**
 * What passes between the page around a world frame and the frame that
 * shows a world made from the visitor's own file (importFrame.ts).
 *
 * Two messages, both plain objects tagged `worldImport: 1`:
 *
 *   models   `models`: the files as they came off the visitor's computer,
 *            each a name and bytes. Page to frame: convert these and show
 *            the world.
 *   world    `title` and `files`: a world folder, each file a path and
 *            bytes. Page to frame: show this world, which is already built.
 *            Frame to page: this is the world made from the models, to save
 *            or publish.
 *
 * A Blender file is converted in a window of its own on the frame's host
 * (blendWindow.ts), and that window speaks to the page that opened it in the
 * same two messages and one more:
 *
 *   blend    `blend`: one word, window to page, and nothing with it.
 *            `waiting`: the window is ready to be handed the models. The
 *            other four answer a window asked for the world that has none
 *            to give: Blender is still `converting`; it `failed`; its
 *            window has `stopped` (closed, or stuck); or nothing is kept
 *            there at all, `empty`. Why a conversion failed is said in
 *            Blender's own window and is not sent.
 *
 * Each side reads a message field by field and treats it as a stranger's.
 * A world is refused unless it is exactly a world folder: every path stays
 * inside the folder, the world's document is among them, and it is no
 * bigger than a world has reason to be. Nothing else rides in either: no
 * text to show, no address, no sign-in.
 *
 * Zero imports.
 */

export const IMPORT_HANDOFF_TAG = 'worldImport';
export const IMPORT_HANDOFF_VERSION = 1;
/** More files than any converted model holds. */
export const MAX_HANDOFF_FILES = 4096;
/** More bytes than any world a browser tab converts: one gigabyte. */
export const MAX_HANDOFF_BYTES = 1024 * 1024 * 1024;
/** A model and the pictures beside it; more than this is not one model. */
export const MAX_MODEL_FILES = 512;
const MAX_PATH_LENGTH = 512;
const MAX_NAME_LENGTH = 255;
const MAX_TITLE_LENGTH = 200;
const WORLD_DOCUMENT = 'index.veml';

export interface HandoffFile {
  path: string;
  bytes: Uint8Array;
}

export interface ImportHandoff {
  title: string;
  files: HandoffFile[];
}

export interface ModelFile {
  /** The file's own name, no directory. */
  name: string;
  bytes: Uint8Array;
}

/** A world as it is posted: the title and each file's path and bytes, nothing else of the caller's objects. */
export function importHandoff(title: string, files: ReadonlyArray<HandoffFile>): Record<string, unknown> {
  return {
    [IMPORT_HANDOFF_TAG]: IMPORT_HANDOFF_VERSION,
    title: title.slice(0, MAX_TITLE_LENGTH),
    files: files.map((f) => ({ path: f.path, bytes: f.bytes })),
  };
}

/** Model files as they are posted: each one's name and bytes, nothing else of the caller's objects. */
export function importModels(models: ReadonlyArray<ModelFile>): Record<string, unknown> {
  return { [IMPORT_HANDOFF_TAG]: IMPORT_HANDOFF_VERSION, models: models.map((m) => ({ name: m.name, bytes: m.bytes })) };
}

/** A path inside the world's folder: plain segments joined by `/`, none of them empty, `.` or `..`. */
const isInsideFolder = (path: unknown): path is string =>
  typeof path === 'string' &&
  path.length > 0 &&
  path.length <= MAX_PATH_LENGTH &&
  !/[\\:?#\u0000-\u001f]/.test(path) &&
  path.split('/').every((part) => part !== '' && part !== '.' && part !== '..');

/** A file's bare name: no directory in it, and not a step out of one. */
const isBareName = (name: unknown): name is string =>
  typeof name === 'string' && name.length > 0 && name.length <= MAX_NAME_LENGTH && !/[\\/\u0000-\u001f]/.test(name) && name !== '.' && name !== '..';

/** By its tag and not `instanceof`: bytes that crossed from another window are that window's kind of array. */
const isBytes = (value: unknown): value is Uint8Array => Object.prototype.toString.call(value) === '[object Uint8Array]';

const tagged = (data: unknown): Record<string, unknown> | null => {
  if (typeof data !== 'object' || data === null || Array.isArray(data)) return null;
  const fields = data as Record<string, unknown>;
  return fields[IMPORT_HANDOFF_TAG] === IMPORT_HANDOFF_VERSION ? fields : null;
};

/** The world in `data`, or null when `data` is not one. Never throws; the answer holds only a world's own fields. */
export function readImportHandoff(data: unknown, maxBytes: number = MAX_HANDOFF_BYTES): ImportHandoff | null {
  try {
    const fields = tagged(data);
    if (fields === null) return null;
    const { title, files } = fields;
    if (typeof title !== 'string' || title.length > MAX_TITLE_LENGTH) return null;
    if (!Array.isArray(files) || files.length === 0 || files.length > MAX_HANDOFF_FILES) return null;
    const out: HandoffFile[] = [];
    let total = 0;
    for (const entry of files as unknown[]) {
      if (typeof entry !== 'object' || entry === null) return null;
      const { path, bytes } = entry as Record<string, unknown>;
      if (!isInsideFolder(path) || !isBytes(bytes)) return null;
      total += bytes.byteLength;
      if (total > maxBytes) return null;
      out.push({ path, bytes });
    }
    return out.some((f) => f.path === WORLD_DOCUMENT) ? { title, files: out } : null;
  } catch {
    return null;
  }
}

/** What a window opened for a Blender file says to the page that opened it. */
export type ImportSignal = 'waiting' | 'empty' | 'converting' | 'failed' | 'stopped';
const SIGNALS: readonly unknown[] = ['waiting', 'empty', 'converting', 'failed', 'stopped'];

/** A word as it is posted: the word and nothing else. */
export function importSignal(word: ImportSignal): Record<string, unknown> {
  return { [IMPORT_HANDOFF_TAG]: IMPORT_HANDOFF_VERSION, blend: word };
}

/** The word in `data`, or null when `data` is not one. Never throws. */
export function readImportSignal(data: unknown): ImportSignal | null {
  try {
    const word = tagged(data)?.blend;
    return SIGNALS.includes(word) ? (word as ImportSignal) : null;
  } catch {
    return null;
  }
}

/** The model files in `data`, or null when `data` is not that. Never throws. */
export function readImportModels(data: unknown, maxBytes: number = MAX_HANDOFF_BYTES): ModelFile[] | null {
  try {
    const fields = tagged(data);
    if (fields === null) return null;
    const { models } = fields;
    if (!Array.isArray(models) || models.length === 0 || models.length > MAX_MODEL_FILES) return null;
    const out: ModelFile[] = [];
    let total = 0;
    for (const entry of models as unknown[]) {
      if (typeof entry !== 'object' || entry === null) return null;
      const { name, bytes } = entry as Record<string, unknown>;
      if (!isBareName(name) || !isBytes(bytes)) return null;
      total += bytes.byteLength;
      if (total > maxBytes) return null;
      out.push({ name, bytes });
    }
    return out;
  } catch {
    return null;
  }
}
